test('只读读取远端文章分类和目录，忽略范围外文件',async()=>{const x=make(),p=new PluginMain(x.app);await p.onload();p.settings.repo='x/y';p.settings.secret='key';x.app.secretStorage={getSecret:()=> 'fake'};const hash=text=>{const b=Buffer.from(text);return require('node:crypto').createHash('sha1').update(Buffer.from(`blob ${b.length}\0`)).update(b).digest('hex');};const a='---\ncategories: 学习\n---\nA',b='---\ncategories: [科技, 编程]\n---\nB',blobs={[hash(a)]:a,[hash(b)]:b};let calls=[];requestHandler=async r=>{calls.push(r);const u=new URL(r.url),path=u.pathname;if(path.endsWith('/git/ref/heads/main'))return {status:200,json:{object:{sha:'head'}}};if(path.endsWith('/git/commits/head'))return {status:200,json:{tree:{sha:'tree'}}};if(path.endsWith('/git/trees/tree'))return {status:200,json:{truncated:false,tree:[{path:'source/_posts/learning',type:'tree',sha:'dir'},{path:'source/_posts/learning/a.md',type:'blob',sha:hash(a)},{path:'source/_posts/b.md',type:'blob',sha:hash(b)},{path:'private.md',type:'blob',sha:'0'.repeat(40)}]}};const sha=path.split('/').at(-1);if(blobs[sha])return {status:200,json:{encoding:'base64',content:Buffer.from(blobs[sha]).toString('base64')}};throw Error(path);};const catalog=await p.readCatalog(()=>true,()=>{});assert.deepEqual(catalog.categories.map(a=>a.join('/')).sort(),['学习','科技','科技/编程']);assert.ok(catalog.directories.includes('source/_posts/learning'));assert.equal(calls.filter(c=>c.method!=='GET').length,0);assert.equal(catalog.skipped,0);p.onunload();});
